  const spegni3 = evento.target.closest("[data-dm-stanza-plancia-spegni]");
  const si = evento.target.closest("[data-dm-stanza-plancia-si]");
  const rimetti2 = evento.target.closest("[data-dm-stanza-plancia-rimetti]");
