    pennello2.ellipse(cx, py + pr * 0.7, pr, pr, 0, 0, Math.PI * 2);
    pennello2.fill();
    pennello2.fillStyle = "rgb(240,214,150)";
    pennello2.beginPath();
    pennello2.ellipse(cx, py + pr * 0.7, pr * 0.45, pr * 0.45, 0, 0, Math.PI * 2);
